const authFlow = (authWindow: BrowserWindow | null): void => {
  const AUTH_URL = 'https://accounts.spotify.com/authorize?'
  const { M_VITE_SPOTIFY_CLIENT_ID, M_VITE_SPOTIFY_URI_CALLBACK } = import.meta.env

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: M_VITE_SPOTIFY_CLIENT_ID,
    scope:
      'streaming user-read-playback-state user-modify-playback-state user-read-currently-playing user-read-email user-read-private app-remote-control user-library-read user-library-modify playlist-modify-private playlist-modify-public',
    redirect_uri: M_VITE_SPOTIFY_URI_CALLBACK
  }).toString()

  authWindow?.loadURL(AUTH_URL + params)

  // Show window for callback
  authWindow?.webContents.on('did-navigate', () => {
    authWindow?.show()
  })

  authWindow?.on('closed', function () {
    authWindow = null
  })
}

app.on('open-url', (_, redirect) => {
  const url = new URL(redirect)
  const authCode = url.searchParams.get('code')

  if (authCode) {
    spotifyApi.authorizationCodeGrant(authCode).then(
      ({ body: { access_token, refresh_token } }) => {
        const credentials = {
          accessToken: access_token,
          refreshToken: refresh_token
        }
        authWindow?.close()
        spotifyApi.setCredentials(credentials)
      },
      (err) => console.error('Error when retrieving access token', err)
    )
  }
})

const createCustomTray = ({ icon, clickWindow, rightClickWindow }: ICustomTray): Tray => {
  const tray = new Tray(icon)
  tray.setIgnoreDoubleClickEvents(true) // required for macOS

  const getWindowPosition = (window: BrowserWindow): { x: number; y: number } => {
    const windowBounds = window.getBounds()
    const trayBounds = tray.getBounds()
    const x = Math.round(trayBounds.x + trayBounds.width / 2 - windowBounds.width / 2)
    const y = Math.round(trayBounds.y + trayBounds.height)
    return { x, y }
  }

  const showWindow = (window: BrowserWindow): void => {
    const position = getWindowPosition(window)
    window.setPosition(position.x, position.y, false)
    window.show()
    window.setVisibleOnAllWorkspaces(true)
    window.focus()
    window.setVisibleOnAllWorkspaces(false)
  }

  const toggleWindow = (window: BrowserWindow): void => {
    if (window.isVisible()) {
      window.hide()
    } else {
      showWindow(window)
    }
  }

  const defaultRightClick = (): void => {
    const menu = [
      {
        role: 'quit',
        accelerator: 'Command+Q'
      } as const
    ]
    tray.popUpContextMenu(Menu.buildFromTemplate(menu))
  }

  tray.on('click', () => toggleWindow(clickWindow))
  tray.on('right-click', () =>
    rightClickWindow ? toggleWindow(rightClickWindow) : defaultRightClick()
  )

  return tray
}

